 1→package filter
 2→
 3→import (
 4→	"errors"
 5→	"fmt"
 6→	"strings"
 7→)
 8→
 9→const (
10→	builtInPrefix = "__ent__/"
11→	userPrefix    = "__ent_user__/"
12→	minMatchLen   = 8
13→)
14→
15→// ValidateFilter checks that a filter is well-formed.
16→// isBuiltIn distinguishes built-in filters (whose replacements start with __ent__/)
17→// from user filters (whose replacements must start with __ent_user__/).
18→func ValidateFilter(f Filter, isBuiltIn bool) error {
19→	if f.Match == "" {
20→		return errors.New("filter match must be non-empty")
21→	}
22→	if f.Replace == "" {
23→		return errors.New("filter replace must be non-empty")
24→	}
25→	if f.Match == f.Replace {
26→		return errors.New("filter match and replace must be different")
27→	}
28→
29→	// Idempotency: applying clean twice must produce the same result.
30→	// This means the replacement string must not itself contain the match pattern,
31→	// AND the match string must not contain the replacement pattern (which would
32→	// cause smudge to corrupt the match).
33→	if strings.Contains(f.Replace, f.Match) {
34→		return fmt.Errorf("filter replace %q must not contain match %q (not idempotent)", f.Replace, f.Match)
35→	}
36→	if strings.Contains(f.Match, f.Replace) {
37→		return fmt.Errorf("filter match %q must not contain replace %q (smudge would corrupt)", f.Match, f.Replace)
38→	}
39→
40→	if isBuiltIn {
41→		if !strings.HasPrefix(f.Replace, builtInPrefix) {
42→			return fmt.Errorf("built-in filter replace must start with %q, got %q", builtInPrefix, f.Replace)
43→		}
44→	} else {
45→		if !strings.HasPrefix(f.Replace, userPrefix) {
46→			return fmt.Errorf("user filter replace must start with %q, got %q", userPrefix, f.Replace)
47→		}
48→		if len(f.Match) < minMatchLen {
49→			return fmt.Errorf("user filter match must be at least %d characters, got %d", minMatchLen, len(f.Match))
50→		}
51→	}
52→
53→	return nil
54→}
