464→	Repo     string // e.g., "org/checkpoints-repo"
465→}
466→
467→// Owner returns the owner portion of the repo field (before the slash).
468→// Returns empty string if the repo field doesn't contain a slash.
469→func (c *CheckpointRemoteConfig) Owner() string {
470→	parts := strings.SplitN(c.Repo, "/", 2)
471→	if len(parts) < 2 {
472→		return ""
473→	}
474→	return parts[0]
