 45→	// LogLevel sets the logging verbosity (debug, info, warn, error).
 46→	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
 47→	// Defaults to "info".
 48→	LogLevel string `json:"log_level,omitempty"`
 49→
 50→	// StrategyOptions contains strategy-specific configuration
 51→	StrategyOptions map[string]any `json:"strategy_options,omitempty"`
 52→
