116→// Load loads the Entire settings from .entire/settings.json,
117→// then applies any overrides from .entire/settings.local.json if it exists.
118→// Returns default settings if neither file exists.
119→// Works correctly from any subdirectory within the repository.
120→func Load(ctx context.Context) (*EntireSettings, error) {
121→	// Get absolute paths for settings files
122→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
123→	if err != nil {
124→		settingsFileAbs = EntireSettingsFile // Fallback to relative
125→	}
126→	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
127→	if err != nil {
128→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
129→	}
130→
131→	// Load base settings
132→	settings, err := loadFromFile(settingsFileAbs)
133→	if err != nil {
134→		return nil, fmt.Errorf("reading settings file: %w", err)
135→	}
136→
137→	// Apply local overrides if they exist
138→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
139→	if err != nil {
140→		if !os.IsNotExist(err) {
141→			return nil, fmt.Errorf("reading local settings file: %w", err)
142→		}
143→		// Local file doesn't exist, continue without overrides
144→	} else {
145→		if err := mergeJSON(settings, localData); err != nil {
146→			return nil, fmt.Errorf("merging local settings: %w", err)
147→		}
148→	}
149→
150→	return settings, nil
151→}
152→
153→// LoadFromFile loads settings from a specific file path without merging local overrides.
154→// Returns default settings if the file doesn't exist.
155→// Use this when you need to display individual settings files separately.
156→func LoadFromFile(filePath string) (*EntireSettings, error) {
157→	return loadFromFile(filePath)
158→}
159→
160→// loadFromFile loads settings from a specific file path.
161→// Returns default settings if the file doesn't exist.
162→func loadFromFile(filePath string) (*EntireSettings, error) {
163→	settings := &EntireSettings{
164→		Enabled: true, // Default to enabled
165→	}
166→
167→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
168→	if err != nil {
169→		if os.IsNotExist(err) {
170→			return settings, nil
171→		}
172→		return nil, fmt.Errorf("%w", err)
173→	}
174→
175→	dec := json.NewDecoder(bytes.NewReader(data))
176→	dec.DisallowUnknownFields()
177→	if err := dec.Decode(settings); err != nil {
178→		return nil, fmt.Errorf("parsing settings file: %w", err)
179→	}
180→
181→	// Validate commit_linking if set
182→	if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
183→		return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
184→	}
185→
186→	return settings, nil
187→}
