189→// mergeJSON merges JSON data into existing settings.
190→// Only non-zero values from the JSON override existing settings.
191→func mergeJSON(settings *EntireSettings, data []byte) error {
192→	// First, validate that there are no unknown keys using strict decoding
193→	dec := json.NewDecoder(bytes.NewReader(data))
194→	dec.DisallowUnknownFields()
195→	var temp EntireSettings
196→	if err := dec.Decode(&temp); err != nil {
197→		return fmt.Errorf("parsing JSON: %w", err)
198→	}
199→
200→	// Parse into a map to check which fields are present
201→	var raw map[string]json.RawMessage
202→	if err := json.Unmarshal(data, &raw); err != nil {
203→		return fmt.Errorf("parsing JSON: %w", err)
204→	}
205→
206→	// Override enabled if present
207→	if enabledRaw, ok := raw["enabled"]; ok {
208→		var e bool
209→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
210→			return fmt.Errorf("parsing enabled field: %w", err)
211→		}
212→		settings.Enabled = e
213→	}
214→
215→	// Override local_dev if present
216→	if localDevRaw, ok := raw["local_dev"]; ok {
217→		var ld bool
218→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
219→			return fmt.Errorf("parsing local_dev field: %w", err)
220→		}
221→		settings.LocalDev = ld
222→	}
223→
224→	// Override absolute_git_hook_path if present
225→	if ahpRaw, ok := raw["absolute_git_hook_path"]; ok {
226→		var ahp bool
227→		if err := json.Unmarshal(ahpRaw, &ahp); err != nil {
228→			return fmt.Errorf("parsing absolute_git_hook_path field: %w", err)
229→		}
230→		settings.AbsoluteGitHookPath = ahp
231→	}
232→
233→	// Override log_level if present and non-empty
234→	if logLevelRaw, ok := raw["log_level"]; ok {
235→		var ll string
236→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
237→			return fmt.Errorf("parsing log_level field: %w", err)
238→		}
239→		if ll != "" {
240→			settings.LogLevel = ll
241→		}
242→	}
243→
244→	// Merge strategy_options if present
245→	if optionsRaw, ok := raw["strategy_options"]; ok {
246→		var opts map[string]any
247→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
248→			return fmt.Errorf("parsing strategy_options field: %w", err)
249→		}
250→		if settings.StrategyOptions == nil {
251→			settings.StrategyOptions = opts
252→		} else {
253→			for k, v := range opts {
254→				settings.StrategyOptions[k] = v
255→			}
256→		}
257→	}
258→
259→	// Override telemetry if present
260→	if telemetryRaw, ok := raw["telemetry"]; ok {
261→		var t bool
262→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
263→			return fmt.Errorf("parsing telemetry field: %w", err)
264→		}
265→		settings.Telemetry = &t
266→	}
267→
268→	// Merge redaction sub-fields if present (field-level, not wholesale replace).
269→	if redactionRaw, ok := raw["redaction"]; ok {
270→		if settings.Redaction == nil {
271→			settings.Redaction = &RedactionSettings{}
272→		}
273→		if err := mergeRedaction(settings.Redaction, redactionRaw); err != nil {
274→			return fmt.Errorf("parsing redaction field: %w", err)
275→		}
276→	}
277→
278→	// Override commit_linking if present and non-empty
279→	if commitLinkingRaw, ok := raw["commit_linking"]; ok {
280→		var cl string
281→		if err := json.Unmarshal(commitLinkingRaw, &cl); err != nil {
282→			return fmt.Errorf("parsing commit_linking field: %w", err)
283→		}
284→		if cl != "" {
285→			switch cl {
286→			case CommitLinkingAlways, CommitLinkingPrompt:
287→				settings.CommitLinking = cl
288→			default:
289→				return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
290→			}
291→		}
292→	}
293→
294→	// Override transcript_filters if present (wholesale replace, not merge)
295→	if tfRaw, ok := raw["transcript_filters"]; ok {
296→		var tf []TranscriptFilter
297→		if err := json.Unmarshal(tfRaw, &tf); err != nil {
298→			return fmt.Errorf("parsing transcript_filters field: %w", err)
299→		}
300→		settings.TranscriptFilters = tf
301→	}
302→
303→	// Override external_agents if present
304→	if externalAgentsRaw, ok := raw["external_agents"]; ok {
305→		var ea bool
306→		if err := json.Unmarshal(externalAgentsRaw, &ea); err != nil {
307→			return fmt.Errorf("parsing external_agents field: %w", err)
308→		}
309→		settings.ExternalAgents = ea
310→	}
311→
312→	return nil
313→}
